package com.example.ancapp.ui.viewmodels

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.FhirRepository
import com.example.ancapp.data.PatientItem
import com.example.ancapp.data.VisitItem
import dev.ohs.fhir.model.r4.QuestionnaireResponse
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class MainViewModel(application: Application) : AndroidViewModel(application) {
  val repository = FhirRepository(application)

  private val _patients = MutableStateFlow<List<PatientItem>>(emptyList())
  val patients: StateFlow<List<PatientItem>> = _patients.asStateFlow()

  private val _selectedPatient = MutableStateFlow<PatientItem?>(null)
  val selectedPatient: StateFlow<PatientItem?> = _selectedPatient.asStateFlow()

  private val _visits = MutableStateFlow<List<VisitItem>>(emptyList())
  val visits: StateFlow<List<VisitItem>> = _visits.asStateFlow()

  private val _questionnaireJson = MutableStateFlow<String?>(null)
  val questionnaireJson: StateFlow<String?> = _questionnaireJson.asStateFlow()

  private val _isLoading = MutableStateFlow(false)
  val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

  fun loadPatients() {
    viewModelScope.launch {
      _isLoading.value = true
      try {
        _patients.value = repository.getPatients()
      } catch (e: Exception) {
        e.printStackTrace()
      } finally {
        _isLoading.value = false
      }
    }
  }

  fun loadPatientDetails(patientId: String) {
    viewModelScope.launch {
      _isLoading.value = true
      try {
        _selectedPatient.value = repository.getPatient(patientId)
        _visits.value = repository.getVisits(patientId)
      } catch (e: Exception) {
        e.printStackTrace()
      } finally {
        _isLoading.value = false
      }
    }
  }

  fun loadQuestionnaire() {
    viewModelScope.launch {
      try {
        _questionnaireJson.value = repository.getQuestionnaireJson()
      } catch (e: Exception) {
        e.printStackTrace()
      }
    }
  }

  fun saveVisit(
    patientId: String,
    response: QuestionnaireResponse,
    onSaved: () -> Unit,
  ) {
    viewModelScope.launch {
      _isLoading.value = true
      try {
        repository.saveVisit(patientId, response)
        // Refresh patient details and visits
        _visits.value = repository.getVisits(patientId)
        _selectedPatient.value = repository.getPatient(patientId)
        onSaved()
      } catch (e: Exception) {
        e.printStackTrace()
      } finally {
        _isLoading.value = false
      }
    }
  }
}

package com.example.ancapp.ui.screens

import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Refresh
import androidx.compose.material.icons.filled.Sync
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import com.example.ancapp.data.PatientItem

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
  patients: List<PatientItem>,
  isLoading: Boolean,
  isSyncing: Boolean,
  syncStatus: String?,
  onSyncClick: () -> Unit,
  onPatientClick: (String) -> Unit,
) {
  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text("ANC Register", fontWeight = FontWeight.Bold)
            Text(
              text = if (isSyncing) "Syncing with server…" else (syncStatus ?: "Ready"),
              style = MaterialTheme.typography.bodySmall,
              color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
          }
        },
        actions = {
          IconButton(onClick = onSyncClick, enabled = !isSyncing) {
            if (isSyncing) {
              CircularProgressIndicator(
                modifier = Modifier.size(24.dp),
                strokeWidth = 2.dp,
                color = MaterialTheme.colorScheme.primary,
              )
            } else {
              Icon(imageVector = Icons.Default.Sync, contentDescription = "Sync with server")
            }
          }
        },
      )
    },
  ) { paddingValues ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(paddingValues),
    ) {
      if (patients.isEmpty() && !isLoading) {
        Column(
          modifier = Modifier
            .fillMaxSize()
            .padding(24.dp),
          horizontalAlignment = Alignment.CenterHorizontally,
          verticalArrangement = Arrangement.Center,
        ) {
          Text(
            text = "No pregnant patients loaded",
            style = MaterialTheme.typography.titleMedium,
          )
          Spacer(modifier = Modifier.height(8.dp))
          Text(
            text = "Tap the sync button above to fetch data from the FHIR server.",
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
          )
          Spacer(modifier = Modifier.height(16.dp))
          Button(onClick = onSyncClick, enabled = !isSyncing) {
            Icon(Icons.Default.Refresh, contentDescription = null)
            Spacer(modifier = Modifier.width(8.dp))
            Text("Sync Now")
          }
        }
      } else {
        LazyColumn(
          modifier = Modifier.fillMaxSize(),
          contentPadding = PaddingValues(16.dp),
          verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
          item {
            Text(
              text = "Currently Pregnant Patients (${patients.size})",
              style = MaterialTheme.typography.titleSmall,
              fontWeight = FontWeight.SemiBold,
              color = MaterialTheme.colorScheme.primary,
            )
          }

          items(patients, key = { it.id }) { patient ->
            PatientCard(patient = patient, onClick = { onPatientClick(patient.id) })
          }
        }
      }

      if (isLoading && patients.isEmpty()) {
        CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
      }
    }
  }
}

@Composable
fun PatientCard(
  patient: PatientItem,
  onClick: () -> Unit,
) {
  ElevatedCard(
    modifier = Modifier
      .fillMaxWidth()
      .clickable(onClick = onClick),
  ) {
    Column(
      modifier = Modifier
        .fillMaxWidth()
        .padding(16.dp),
    ) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Text(
          text = patient.name,
          style = MaterialTheme.typography.titleMedium,
          fontWeight = FontWeight.Bold,
        )
        patient.age?.let { age ->
          AssistChip(
            onClick = {},
            label = { Text("$age yrs") },
            enabled = false,
          )
        }
      }

      Spacer(modifier = Modifier.height(8.dp))

      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
      ) {
        Column {
          Text(
            text = "Estimated Due Date",
            style = MaterialTheme.typography.labelMedium,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            text = patient.estimatedDueDate?.toString() ?: "Not recorded",
            style = MaterialTheme.typography.bodyLarge,
            fontWeight = FontWeight.Medium,
          )
        }

        Column(horizontalAlignment = Alignment.End) {
          Text(
            text = "Current Gestational Age",
            style = MaterialTheme.typography.labelMedium,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            text = patient.gestationalAgeWeeks?.let { "$it weeks" } ?: "—",
            style = MaterialTheme.typography.bodyLarge,
            fontWeight = FontWeight.Medium,
            color = MaterialTheme.colorScheme.primary,
          )
        }
      }
    }
  }
}

