                      Text(
                        text = p.gestationalAgeWeeks?.let { "$it weeks" } ?: "—",
                        style = MaterialTheme.typography.bodyLarge,
                        fontWeight = FontWeight.SemiBold,
                        color = MaterialTheme.colorScheme.primary,
                      )
                    }
                  }
                }
              }
            }
          }

          // Past ANC Visits Header
          item {
            Text(
              text = "Past ANC Visits (${visits.size})",
              style = MaterialTheme.typography.titleMedium,
              fontWeight = FontWeight.Bold,
            )
          }

          if (visits.isEmpty()) {
            item {
              Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(
                  containerColor = MaterialTheme.colorScheme.surfaceContainerLow,
                ),
              ) {
                Box(
                  modifier = Modifier
                    .fillMaxWidth()
                    .padding(32.dp),
                  contentAlignment = Alignment.Center,
                ) {
                  Text(
                    text = "No past visits recorded.",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.outline,
                  )
                }
              }
            }
          } else {
            items(visits, key = { it.encounterId }) { visit ->
              VisitCard(visit = visit)
            }
          }

          // Bottom spacing for FAB
          item {
            Spacer(modifier = Modifier.height(72.dp))
          }
        }
      }
    }
  }
}

@Composable
fun VisitCard(visit: VisitItem) {
  OutlinedCard(
    modifier = Modifier.fillMaxWidth(),
  ) {
    Column(
      modifier = Modifier
        .fillMaxWidth()
        .padding(16.dp),
      verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Text(
          text = "Visit: ${visit.date}",
          style = MaterialTheme.typography.titleMedium,
          fontWeight = FontWeight.Bold,
          color = MaterialTheme.colorScheme.primary,
        )
        visit.gestationalAge?.let { ga ->
          AssistChip(
            onClick = {},
            label = { Text(ga) },
            enabled = false,
          )
        }
      }

      HorizontalDivider(modifier = Modifier.padding(vertical = 4.dp))

      // Vitals Grid
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
      ) {
        Column(modifier = Modifier.weight(1f)) {
          Text(
            text = "Weight",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            text = visit.weight ?: "—",
            style = MaterialTheme.typography.bodyMedium,
            fontWeight = FontWeight.Medium,
          )
        }

        Column(modifier = Modifier.weight(1f)) {
          Text(
            text = "Blood Pressure",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            text = visit.bloodPressure ?: "—",
            style = MaterialTheme.typography.bodyMedium,
            fontWeight = FontWeight.Medium,
          )
        }

        if (visit.hemoglobin != null) {
          Column(modifier = Modifier.weight(1f)) {
            Text(
              text = "Hemoglobin",
              style = MaterialTheme.typography.labelSmall,
              color = MaterialTheme.colorScheme.outline,
            )
            Text(
              text = visit.hemoglobin,
              style = MaterialTheme.typography.bodyMedium,
              fontWeight = FontWeight.Medium,
            )
          }
        }
      }

      // Danger signs if any
      if (visit.dangerSigns.isNotEmpty()) {
        Column(modifier = Modifier.padding(top = 4.dp)) {
          Text(
            text = "Danger signs:",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.error,
          )
          Text(
            text = visit.dangerSigns.joinToString(", "),
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.error,
            fontWeight = FontWeight.Medium,
          )
        }
      }

      // Notes if any
      if (!visit.notes.isNullOrBlank()) {
        Column(modifier = Modifier.padding(top = 4.dp)) {
          Text(
            text = "Notes:",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            text = visit.notes,
            style = MaterialTheme.typography.bodySmall,
          )
        }
      }
    }
  }
}

package com.example.ancapp.ui.screens

import androidx.compose.foundation.layout.*
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import dev.ohs.fhir.datacapture.Questionnaire
import dev.ohs.fhir.datacapture.QuestionnaireConfig
import dev.ohs.fhir.model.r4.QuestionnaireResponse
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.launch

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RecordVisitScreen(
  questionnaireJson: String?,
  onSave: (QuestionnaireResponse) -> Unit,
  onCancel: () -> Unit,
) {
  val scope = rememberCoroutineScope()

  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("Record ANC Visit") },
        navigationIcon = {
          IconButton(onClick = onCancel) {
            Icon(
              imageVector = Icons.AutoMirrored.Filled.ArrowBack,
              contentDescription = "Cancel",
            )
          }
        },
      )
    },
  ) { paddingValues ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(paddingValues),
    ) {
      if (questionnaireJson == null) {
        CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
      } else {
        Questionnaire(
          questionnaireJson = questionnaireJson,
          config = QuestionnaireConfig(
            showSubmitButton = true,
            showCancelButton = true,
            submitButtonText = "Save Visit",
          ),
          onSubmit = { getResponse ->
            scope.launch {
              try {
                val response = getResponse()
                onSave(response)
              } catch (e: CancellationException) {
                // Validation error, form displays errors inline
              }
            }
          },
          onCancel = onCancel,
        )
      }
    }
  }
}

package com.example.ancapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.viewModels
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import com.example.ancapp.ui.screens.PatientDetailScreen
import com.example.ancapp.ui.screens.RecordVisitScreen
import com.example.ancapp.ui.screens.RegisterScreen
import com.example.ancapp.ui.viewmodels.MainViewModel
import com.example.ancapp.ui.viewmodels.SyncViewModel

class MainActivity : ComponentActivity() {
  private val mainViewModel: MainViewModel by viewModels()
  private val syncViewModel: SyncViewModel by viewModels()

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)

    // Load initial local data
    mainViewModel.loadPatients()

    // Trigger one-time sync from server on startup
    syncViewModel.syncNow {
      mainViewModel.loadPatients()
    }

    setContent {
      MaterialTheme {
        Surface(modifier = Modifier.fillMaxSize()) {
          val navController = rememberNavController()

          val patients by mainViewModel.patients.collectAsState()
          val selectedPatient by mainViewModel.selectedPatient.collectAsState()
          val visits by mainViewModel.visits.collectAsState()
          val questionnaireJson by mainViewModel.questionnaireJson.collectAsState()
          val isLoading by mainViewModel.isLoading.collectAsState()

          val syncStatus by syncViewModel.syncState.collectAsState()
          val isSyncing by syncViewModel.isSyncing.collectAsState()

          NavHost(navController = navController, startDestination = "register") {
            composable("register") {
              RegisterScreen(
                patients = patients,
                isLoading = isLoading,
                isSyncing = isSyncing,
                syncStatus = syncStatus,
                onSyncClick = {
                  syncViewModel.syncNow {
                    mainViewModel.loadPatients()
                  }
                },
                onPatientClick = { patientId ->
                  navController.navigate("patient/$patientId")
                },
              )
            }

            composable(
              route = "patient/{patientId}",
              arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
            ) { backStackEntry ->
              val patientId = backStackEntry.arguments?.getString("patientId") ?: ""
              LaunchedEffect(patientId) {
                mainViewModel.loadPatientDetails(patientId)
              }

              PatientDetailScreen(
                patient = selectedPatient,
                visits = visits,
                isLoading = isLoading,
                onBackClick = { navController.popBackStack() },
                onRecordNewVisitClick = {
                  navController.navigate("newVisit/$patientId")
                },
              )
            }

            composable(
              route = "newVisit/{patientId}",
              arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
            ) { backStackEntry ->
              val patientId = backStackEntry.arguments?.getString("patientId") ?: ""
              LaunchedEffect(patientId) {
                mainViewModel.loadQuestionnaire()
              }

              RecordVisitScreen(
                questionnaireJson = questionnaireJson,
                onSave = { response ->
                  mainViewModel.saveVisit(patientId, response) {
                    syncViewModel.syncNow()
                    navController.popBackStack()
                  }
                },
                onCancel = {
                  navController.popBackStack()
                },
              )
            }
          }
        }
      }
    }
  }
}
